css:
.gradient-btn {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 15px 40px;
  border: none;
  border-radius: 50px;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.4);
}

.gradient-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 25px rgba(102, 126, 234, 0.6);
}

.flip-card {
  width: 300px;
  height: 400px;
  perspective: 1000px;
}

.flip-card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.6s;
  transform-style: preserve-3d;
}

.flip-card:hover .flip-card-inner {
  transform: rotateY(180deg);
}

.flip-card-front, .flip-card-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.flip-card-front {
  background: white;
}

.flip-card-back {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  transform: rotateY(180deg);
}

.login-form {
  background: white;
  padding: 40px;
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0,0,0,0.1);
  max-width: 400px;
}

.input-group {
  position: relative;
  margin: 30px 0;
}

.input-group input {
  width: 100%;
  padding: 15px;
  border: 2px solid #e0e0e0;
  border-radius: 10px;
  font-size: 16px;
  transition: all 0.3s;
}

.input-group input:focus {
  border-color: #667eea;
  outline: none;
}

.input-group label {
  position: absolute;
  top: 15px;
  right: 15px;
  transition: all 0.3s;
  color: #999;
  pointer-events: none;
}

.input-group input:focus ~ label,
.input-group input:valid ~ label {
  top: -10px;
  right: 10px;
  font-size: 12px;
  color: #667eea;
  background: white;
  padding: 0 5px;
}

.menu-toggle {
  width: 30px;
  height: 25px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.menu-toggle span {
  width: 100%;
  height: 3px;
  background: #333;
  transition: all 0.3s;
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(8px, 8px);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(8px, -8px);
}

.mobile-menu {
  position: fixed;
  top: 0;
  right: -300px;
  width: 300px;
  height: 100vh;
  background: white;
  box-shadow: -5px 0 15px rgba(0,0,0,0.1);
  transition: right 0.3s;
  padding: 80px 30px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.mobile-menu.active {
  right: 0;
}

.slider {
  position: relative;
  width: 100%;
  height: 400px;
  overflow: hidden;
  border-radius: 15px;
}

.slides {
  display: flex;
  transition: transform 0.5s ease;
}

.slide {
  min-width: 100%;
  height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2em;
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
}

.dots {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(255,255,255,0.5);
  cursor: pointer;
  transition: all 0.3s;
}

.dot.active {
  background: white;
  transform: scale(1.3);
}

js:
let currentSlide = 0;
const slides = document.querySelectorAll('.slide');
const dots = document.querySelectorAll('.dot');

function showSlide(n) {
  slides.forEach((slide, i) => {
    slide.classList.toggle('active', i === n);
  });
  dots.forEach((dot, i) => {
    dot.classList.toggle('active', i === n);
  });
  document.querySelector('.slides').style.transform = `translateX(-${n * 100}%)`;
}

setInterval(() => {
  currentSlide = (currentSlide + 1) % slides.length;
  showSlide(currentSlide);
}, 3000);

css:
.neon-btn {
  background: transparent;
  color: #00ff00;
  padding: 20px 50px;
  border: 3px solid #00ff00;
  border-radius: 10px;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.3s;
  box-shadow: 0 0 10px #00ff00, inset 0 0 10px #00ff00;
}

.neon-btn:hover {
  background: #00ff00;
  color: #000;
  box-shadow: 0 0 30px #00ff00, inset 0 0 30px #00ff00;
}

.profile-card {
  background: white;
  padding: 30px;
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0,0,0,0.1);
  text-align: center;
  max-width: 300px;
}

.profile-img {
  width: 120px;
  height: 120px;
  background: linear-gradient(135deg, #667eea, #764ba2);
  border-radius: 50%;
  margin: 0 auto 20px;
}

.profile-card h3 {
  margin: 10px 0;
  font-size: 24px;
}

.role {
  color: #999;
  margin-bottom: 20px;
}

.stats {
  display: flex;
  justify-content: space-around;
  margin: 20px 0;
  padding: 20px 0;
  border-top: 1px solid #eee;
  border-bottom: 1px solid #eee;
}

.stats div {
  display: flex;
  flex-direction: column;
}

.register-form {
  background: linear-gradient(135deg, #667eea, #764ba2);
  padding: 50px;
  border-radius: 20px;
  max-width: 400px;
  color: white;
}

.register-form h2 {
  margin-bottom: 30px;
  text-align: center;
}

.register-form input {
  width: 100%;
  padding: 15px;
  margin: 10px 0;
  border: none;
  border-radius: 10px;
  font-size: 16px;
  background: rgba(255,255,255,0.9);
}

.register-form button {
  width: 100%;
  padding: 15px;
  margin-top: 20px;
  border: 2px solid white;
  border-radius: 10px;
  background: transparent;
  color: white;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s;
}

.register-form button:hover {
  background: white;
  color: #667eea;
}

.dropdown {
  position: relative;
  display: inline-block;
}

.dropdown-btn {
  padding: 12px 30px;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
}

.dropdown-content {
  display: none;
  position: absolute;
  background: white;
  min-width: 200px;
  box-shadow: 0 8px 16px rgba(0,0,0,0.2);
  border-radius: 8px;
  margin-top: 10px;
  z-index: 1;
}

.dropdown:hover .dropdown-content {
  display: block;
  animation: fadeIn 0.3s;
}

.dropdown-content a {
  display: block;
  padding: 12px 16px;
  text-decoration: none;
  color: #333;
  transition: background 0.2s;
}

.dropdown-content a:hover {
  background: #f0f0f0;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

.spinner {
  width: 50px;
  height: 50px;
  border: 5px solid #f3f3f3;
  border-top: 5px solid #667eea;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.progress-bar {
  width: 100%;
  height: 30px;
  background: #f0f0f0;
  border-radius: 15px;
  overflow: hidden;
}

.progress {
  height: 100%;
  background: linear-gradient(90deg, #667eea, #764ba2);
  border-radius: 15px;
  transition: width 1s ease;
  animation: shimmer 2s infinite;
}

@keyframes shimmer {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.8; }
}

.ripple-btn {
  position: relative;
  overflow: hidden;
  padding: 15px 40px;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  cursor: pointer;
}

.ripple-btn::after {
  content: '';
  position: absolute;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255,255,255,0.5);
  transform: translate(-50%, -50%);
  transition: width 0.6s, height 0.6s;
}

.ripple-btn:active::after {
  width: 300px;
  height: 300px;
}

.glass-card {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 20px;
  padding: 30px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 32px rgba(0,0,0,0.1);
}

.glass-card h3 {
  margin: 0 0 15px;
  color: #333;
}

.glass-card p {
  margin: 0 0 20px;
  color: #666;
}

.glass-card button {
  padding: 10px 25px;
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

.modal-overlay {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0,0,0,0.5);
  z-index: 1000;
}

.modal-overlay.active {
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-box {
  background: white;
  padding: 40px;
  border-radius: 15px;
  max-width: 500px;
  position: relative;
  animation: modalSlide 0.3s;
}

@keyframes modalSlide {
  from { transform: translateY(-50px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.tabs {
  display: flex;
  border-bottom: 2px solid #eee;
}

.tab {
  padding: 15px 30px;
  cursor: pointer;
  transition: all 0.3s;
  border-bottom: 3px solid transparent;
}

.tab.active {
  color: #667eea;
  border-bottom-color: #667eea;
}

.content {
  display: none;
  padding: 20px;
  animation: fadeIn 0.5s;
}

.content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

js:
document.querySelectorAll('.tab').forEach(tab => {
  tab.onclick = () => {
    const tabNum = tab.getAttribute('data-tab');
    document.querySelectorAll('.tab, .content').forEach(el => el.classList.remove('active'));
    tab.classList.add('active');
    document.querySelector(`[data-content="${tabNum}"]`).classList.add('active');
  };
});

css:
.tooltip-btn {
  position: relative;
  padding: 12px 24px;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

.tooltip-btn::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%) scale(0);
  background: #333;
  color: white;
  padding: 8px 12px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  transition: all 0.3s;
}

.tooltip-btn:hover::after {
  transform: translateX(-50%) scale(1);
  opacity: 1;
}

.badge {
  display: inline-block;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
}

.badge-success {
  background: #10b981;
  color: white;
}

.badge-warning {
  background: #f59e0b;
  color: white;
}

.badge-error {
  background: #ef4444;
  color: white;
}

.accordion-item {
  border: 1px solid #eee;
  border-radius: 8px;
  margin: 10px 0;
}

.accordion-header {
  padding: 15px;
  cursor: pointer;
  background: #f9f9f9;
  font-weight: 600;
  transition: background 0.3s;
}

.accordion-header:hover {
  background: #f0f0f0;
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  padding: 0 15px;
  transition: all 0.3s;
}

.accordion-item.active .accordion-content {
  max-height: 200px;
  padding: 15px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  background: #f9f9f9;
  border-radius: 8px;
}

.breadcrumb a {
  color: #667eea;
  text-decoration: none;
  transition: color 0.2s;
}

.breadcrumb a:hover {
  color: #764ba2;
  text-decoration: underline;
}

.breadcrumb span:last-child {
  color: #999;
}

.pagination {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.page-btn {
  padding: 10px 15px;
  border: 1px solid #ddd;
  background: white;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s;
}

.page-btn:hover {
  background: #f0f0f0;
}

.page-btn.active {
  background: #667eea;
  color: white;
  border-color: #667eea;
}
